using System;
using System.Collections;
using UnityEngine;
using UnityEngine.Events;

[DisallowMultipleComponent]
[RequireComponent(typeof(Rigidbody2D))]
public class PlayerController : MonoBehaviour
{
    public enum ShipState
    {
        Flying,
        Docking,
        Docked,
        Undocking
    }

    [Header("Movement")]
    [SerializeField, Min(0f)] private float thrustForce = 18f;
    [SerializeField, Min(0f)] private float reverseThrustForce = 9f;
    [SerializeField, Min(0f)] private float strafeForce = 10f;
    [SerializeField, Min(0f)] private float rotationTorque = 14f;
    [SerializeField, Min(0f)] private float maxSpeed = 22f;
    [SerializeField, Min(0f)] private float maxAngularSpeed = 180f;
    [SerializeField, Min(0f)] private float brakeForce = 3.5f;
    [SerializeField, Min(0f)] private float idleLinearDamping = 0.15f;
    [SerializeField, Min(0f)] private float idleAngularDamping = 2.5f;

    [Header("Fuel")]
    [SerializeField, Min(1f)] private float maxFuel = 100f;
    [SerializeField, Min(0f)] private float thrustFuelConsumption = 4f;
    [SerializeField, Min(0f)] private float strafeFuelConsumption = 2.5f;
    [SerializeField, Min(0f)] private float refuelRate = 25f;
    [SerializeField] private float currentFuel = 100f;

    [Header("Docking")]
    [SerializeField] private string stationTag = "Station";
    [SerializeField] private string dockingPortName = "DockingPort";
    [SerializeField] private KeyCode dockKey = KeyCode.F;
    [SerializeField, Min(0.1f)] private float dockingDuration = 1.6f;
    [SerializeField, Min(0f)] private float maxDockingRelativeSpeed = 3f;
    [SerializeField, Min(0f)] private float undockForce = 4f;
    [SerializeField, Min(0f)] private float undockControlLockTime = 0.35f;

    [Header("Effects")]
    [SerializeField] private ParticleSystem mainThrusterParticles;
    [SerializeField] private ParticleSystem reverseThrusterParticles;
    [SerializeField] private ParticleSystem leftStrafeParticles;
    [SerializeField] private ParticleSystem rightStrafeParticles;
    [SerializeField] private Transform mainThrusterFlame;
    [SerializeField] private AudioSource thrustAudioSource;
    [SerializeField, Range(0f, 1f)] private float maxThrustVolume = 0.6f;

    [Header("Events")]
    public UnityEvent OnDocked;
    public UnityEvent OnUndocked;
    public UnityEvent<bool> OnDockingAvailableChanged;
    public UnityEvent<string> OnDockingFailed;
    public UnityEvent<float> OnFuelChanged;

    public event Action OnDockedEvent;
    public event Action OnUndockedEvent;
    public event Action<float> OnFuelChangedEvent;

    public ShipState CurrentState { get; private set; } = ShipState.Flying;
    public bool IsDocked => CurrentState == ShipState.Docked;
    public bool CanDock => CurrentState == ShipState.Flying && currentDockingPort != null && GetRelativeDockingSpeed() <= maxDockingRelativeSpeed;
    public float FuelNormalized => maxFuel > 0f ? Mathf.Clamp01(currentFuel / maxFuel) : 0f;
    public float CurrentFuel => currentFuel;
    public float Speed => cachedRigidbody != null ? cachedRigidbody.velocity.magnitude : 0f;
    public Vector2 Velocity => cachedRigidbody != null ? cachedRigidbody.velocity : Vector2.zero;
    public Transform CurrentDockingPort => currentDockingPort;

    private Rigidbody2D cachedRigidbody;
    private Transform currentDockingPort;
    private Transform currentStationRoot;
    private Rigidbody2D currentStationBody;
    private Coroutine dockingCoroutine;
    private Vector3 mainFlameInitialScale = Vector3.one;

    private float thrustInput;
    private float rotationInput;
    private float strafeInput;
    private bool brakeInput;
    private bool wasDockingAvailable;
    private float lastFuelNormalized = -1f;

    private void Awake()
    {
        cachedRigidbody = GetComponent<Rigidbody2D>();
        cachedRigidbody.gravityScale = 0f;
        cachedRigidbody.interpolation = RigidbodyInterpolation2D.Interpolate;
        cachedRigidbody.collisionDetectionMode = CollisionDetectionMode2D.Continuous;

        currentFuel = Mathf.Clamp(currentFuel, 0f, maxFuel);

        if (mainThrusterFlame != null)
            mainFlameInitialScale = mainThrusterFlame.localScale;

        SetParticleEmission(mainThrusterParticles, false);
        SetParticleEmission(reverseThrusterParticles, false);
        SetParticleEmission(leftStrafeParticles, false);
        SetParticleEmission(rightStrafeParticles, false);

        if (thrustAudioSource != null)
        {
            thrustAudioSource.loop = true;
            thrustAudioSource.playOnAwake = false;
            thrustAudioSource.volume = 0f;
        }
    }

    private void OnEnable()
    {
        NotifyFuelChanged(true);
    }

    private void OnDisable()
    {
        StopThrustEffects();

        if (dockingCoroutine != null)
        {
            StopCoroutine(dockingCoroutine);
            dockingCoroutine = null;
        }
    }

    private void Update()
    {
        if (CurrentState == ShipState.Docked && transform.parent == null && currentDockingPort == null)
        {
            RestoreFlightPhysics();
            CurrentState = ShipState.Flying;
        }

        if (Input.GetKeyDown(dockKey))
        {
            if (CurrentState == ShipState.Docked)
                Undock();
            else if (CurrentState == ShipState.Flying)
                TryDock();
        }

        if (CurrentState == ShipState.Docked)
        {
            Refuel(refuelRate * Time.deltaTime);
            StopThrustEffects();
        }

        bool available = CanDock;
        if (available != wasDockingAvailable)
        {
            wasDockingAvailable = available;
            OnDockingAvailableChanged?.Invoke(available);
        }

        NotifyFuelChanged(false);
    }

    private void FixedUpdate()
    {
        ReadInput();

        if (CurrentState != ShipState.Flying)
        {
            if (CurrentState == ShipState.Flying || CurrentState == ShipState.Undocking)
                return;

            if (CurrentState != ShipState.Docked)
                return;

            return;
        }

        ApplyRotation();
        ApplyThrust();
        ApplyBrakingAndDamping();
        ClampVelocity();
        UpdateEffects();
    }

    private void ReadInput()
    {
        if (CurrentState != ShipState.Flying)
        {
            thrustInput = 0f;
            rotationInput = 0f;
            strafeInput = 0f;
            brakeInput = false;
            return;
        }

        thrustInput = Input.GetAxisRaw("Vertical");
        rotationInput = Input.GetAxisRaw("Horizontal");
        strafeInput = 0f;

        if (Input.GetKey(KeyCode.Q))
            strafeInput -= 1f;
        if (Input.GetKey(KeyCode.E))
            strafeInput += 1f;

        brakeInput = Input.GetKey(KeyCode.Space) || Input.GetKey(KeyCode.LeftShift);
    }

    private void ApplyRotation()
    {
        if (Mathf.Abs(rotationInput) > 0.01f)
        {
            cachedRigidbody.AddTorque(-rotationInput * rotationTorque, ForceMode2D.Force);
        }
        else if (!brakeInput)
        {
            cachedRigidbody.angularVelocity = Mathf.MoveTowards(
                cachedRigidbody.angularVelocity,
                0f,
                idleAngularDamping * 50f * Time.fixedDeltaTime);
        }

        cachedRigidbody.angularVelocity = Mathf.Clamp(
            cachedRigidbody.angularVelocity,
            -maxAngularSpeed,
            maxAngularSpeed);
    }

    private void ApplyThrust()
    {
        if (currentFuel <= 0f)
        {
            thrustInput = 0f;
            strafeInput = 0f;
            return;
        }

        float fuelUsed = 0f;

        if (thrustInput > 0.01f)
        {
            cachedRigidbody.AddForce((Vector2)transform.up * (thrustInput * thrustForce), ForceMode2D.Force);
            fuelUsed += thrustFuelConsumption * thrustInput * Time.fixedDeltaTime;
        }
        else if (thrustInput < -0.01f)
        {
            cachedRigidbody.AddForce((Vector2)transform.up * (thrustInput * reverseThrustForce), ForceMode2D.Force);
            fuelUsed += thrustFuelConsumption * Mathf.Abs(thrustInput) * 0.6f * Time.fixedDeltaTime;
        }

        if (Mathf.Abs(strafeInput) > 0.01f)
        {
            cachedRigidbody.AddForce((Vector2)transform.right * (strafeInput * strafeForce), ForceMode2D.Force);
            fuelUsed += strafeFuelConsumption * Mathf.Abs(strafeInput) * Time.fixedDeltaTime;
        }

        if (fuelUsed > 0f)
            ConsumeFuel(fuelUsed);
    }

    private void ApplyBrakingAndDamping()
    {
        if (brakeInput)
        {
            Vector2 targetVelocity = currentStationBody != null ? currentStationBody.velocity : Vector2.zero;
            cachedRigidbody.velocity = Vector2.Lerp(
                cachedRigidbody.velocity,
                targetVelocity,
                1f - Mathf.Exp(-brakeForce * Time.fixedDeltaTime));

            cachedRigidbody.angularVelocity = Mathf.MoveTowards(
                cachedRigidbody.angularVelocity,
                0f,
                brakeForce * 60f * Time.fixedDeltaTime);
        }
        else if (Mathf.Abs(thrustInput) < 0.01f && Mathf.Abs(strafeInput) < 0.01f && idleLinearDamping > 0f)
        {
            cachedRigidbody.velocity = Vector2.Lerp(
                cachedRigidbody.velocity,
                Vector2.zero,
                1f - Mathf.Exp(-idleLinearDamping * Time.fixedDeltaTime));
        }
    }

    private void ClampVelocity()
    {
        if (cachedRigidbody.velocity.sqrMagnitude > maxSpeed * maxSpeed)
            cachedRigidbody.velocity = cachedRigidbody.velocity.normalized * maxSpeed;
    }

    public void TryDock()
    {
        if (CurrentState != ShipState.Flying)
            return;

        if (currentDockingPort == null)
        {
            OnDockingFailed?.Invoke("No station in range.");
            return;
        }

        if (GetRelativeDockingSpeed() > maxDockingRelativeSpeed)
        {
            OnDockingFailed?.Invoke("Approach speed is too high to dock.");
            return;
        }

        if (dockingCoroutine != null)
            StopCoroutine(dockingCoroutine);

        dockingCoroutine = StartCoroutine(DockingRoutine());
    }

    public void Undock()
    {
        if (CurrentState != ShipState.Docked)
            return;

        if (dockingCoroutine != null)
            StopCoroutine(dockingCoroutine);

        dockingCoroutine = StartCoroutine(UndockRoutine());
    }

    private IEnumerator DockingRoutine()
    {
        CurrentState = ShipState.Docking;
        StopThrustEffects();

        Vector3 startPosition = transform.position;
        Quaternion startRotation = transform.rotation;
        RigidbodyType2D previousBodyType = cachedRigidbody.bodyType;

        cachedRigidbody.velocity = Vector2.zero;
        cachedRigidbody.angularVelocity = 0f;
        cachedRigidbody.bodyType = RigidbodyType2D.Kinematic;

        float elapsed = 0f;

        while (elapsed < dockingDuration)
        {
            if (currentDockingPort == null)
            {
                cachedRigidbody.bodyType = previousBodyType;
                CurrentState = ShipState.Flying;
                dockingCoroutine = null;
                OnDockingFailed?.Invoke("Docking aborted: station lost.");
                yield break;
            }

            elapsed += Time.deltaTime;
            float t = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(elapsed / dockingDuration));

            transform.position = Vector3.Lerp(startPosition, currentDockingPort.position, t);
            transform.rotation = Quaternion.Slerp(startRotation, currentDockingPort.rotation, t);

            startPosition = Vector3.Lerp(startPosition, currentDockingPort.position, t * 0.15f);
            startRotation = Quaternion.Slerp(startRotation, currentDockingPort.rotation, t * 0.15f);

            yield return null;
        }

        if (currentDockingPort == null)
        {
            cachedRigidbody.bodyType = previousBodyType;
            CurrentState = ShipState.Flying;
            dockingCoroutine = null;
            yield break;
        }

        transform.position = currentDockingPort.position;
        transform.rotation = currentDockingPort.rotation;

        Transform parent = currentStationRoot != null ? currentStationRoot : currentDockingPort;
        transform.SetParent(parent, true);

        cachedRigidbody.velocity = Vector2.zero;
        cachedRigidbody.angularVelocity = 0f;
        cachedRigidbody.simulated = false;

        CurrentState = ShipState.Docked;
        dockingCoroutine = null;

        OnDocked?.Invoke();
        OnDockedEvent?.Invoke();
    }

    private IEnumerator UndockRoutine()
    {
        CurrentState = ShipState.Undocking;
        StopThrustEffects();

        Transform port = currentDockingPort;
        Vector2 stationVelocity = currentStationBody != null ? currentStationBody.velocity : Vector2.zero;
        Vector2 exitDirection = port != null ? (Vector2)port.up : (Vector2)transform.up;

        transform.SetParent(null, true);
        RestoreFlightPhysics();

        cachedRigidbody.velocity = stationVelocity + exitDirection.normalized * undockForce;
        cachedRigidbody.angularVelocity = 0f;

        OnUndocked?.Invoke();
        OnUndockedEvent?.Invoke();

        yield return new WaitForSeconds(undockControlLockTime);

        CurrentState = ShipState.Flying;
        dockingCoroutine = null;
    }

    private void RestoreFlightPhysics()
    {
        cachedRigidbody.bodyType = RigidbodyType2D.Dynamic;
        cachedRigidbody.simulated = true;
        cachedRigidbody.WakeUp();
    }

    private float GetRelativeDockingSpeed()
    {
        if (cachedRigidbody == null)
            return float.MaxValue;

        Vector2 stationVelocity = currentStationBody != null ? currentStationBody.velocity : Vector2.zero;
        return (cachedRigidbody.velocity - stationVelocity).magnitude;
    }

    private void Refuel(float amount)
    {
        if (amount <= 0f || currentFuel >= maxFuel)
            return;

        currentFuel = Mathf.Min(maxFuel, currentFuel + amount);
    }

    private void ConsumeFuel(float amount)
    {
        currentFuel = Mathf.Max(0f, currentFuel - amount);
    }

    public void AddFuel(float amount)
    {
        if (amount > 0f)
            currentFuel = Mathf.Clamp(currentFuel + amount, 0f, maxFuel);
    }

    public bool ConsumeFuelAmount(float amount)
    {
        if (amount < 0f || currentFuel < amount)
            return false;

        currentFuel -= amount;
        return true;
    }

    private void NotifyFuelChanged(bool force)
    {
        float normalized = FuelNormalized;

        if (!force && Mathf.Approximately(normalized, lastFuelNormalized))
            return;

        lastFuelNormalized = normalized;
        OnFuelChanged?.Invoke(normalized);
        OnFuelChangedEvent?.Invoke(normalized);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (CurrentState == ShipState.Docked || CurrentState == ShipState.Docking)
            return;

        if (!other.CompareTag(stationTag) && !other.CompareTag("DockingPort"))
            return;

        Transform stationRoot = other.transform.root;
        Transform port = null;

        if (other.CompareTag("DockingPort"))
        {
            port = other.transform;
        }
        else
        {
            Transform found = other.transform.Find(dockingPortName);
            if (found == null && stationRoot != null)
                found = stationRoot.Find(dockingPortName);

            port = found != null ? found : other.transform;
        }

        currentDockingPort = port;
        currentStationRoot = stationRoot != null ? stationRoot : other.transform;
        currentStationBody = currentStationRoot.GetComponent<Rigidbody2D>();

        if (currentStationBody == null && currentStationRoot.parent != null)
            currentStationBody = currentStationRoot.GetComponentInParent<Rigidbody2D>();
    }

    private void OnTriggerExit2D(Collider2D other)
    {
        if (CurrentState == ShipState.Docked || CurrentState == ShipState.Docking)
            return;

        if (currentStationRoot == null)
            return;

        if (other.transform.root == currentStationRoot || other.transform == currentDockingPort)
        {
            currentDockingPort = null;
            currentStationRoot = null;
            currentStationBody = null;
        }
    }

    private void UpdateEffects()
    {
        bool hasFuel = currentFuel > 0f;
        bool mainActive = hasFuel && thrustInput > 0.01f && CurrentState == ShipState.Flying;
        bool reverseActive = hasFuel && thrustInput < -0.01f && CurrentState == ShipState.Flying;
        bool leftActive = hasFuel && strafeInput < -0.01f && CurrentState == ShipState.Flying;
        bool rightActive = hasFuel && strafeInput > 0.01f && CurrentState == ShipState.Flying;

        SetParticleEmission(mainThrusterParticles, mainActive);
        SetParticleEmission(reverseThrusterParticles, reverseActive);
        SetParticleEmission(leftStrafeParticles, rightActive);
        SetParticleEmission(rightStrafeParticles, leftActive);

        if (mainThrusterFlame != null)
        {
            float flameLength = mainActive ? Mathf.Lerp(0.6f, 1.4f, thrustInput) : 0f;
            mainThrusterFlame.localScale = new Vector3(
                mainFlameInitialScale.x,
                mainFlameInitialScale.y * flameLength,
                mainFlameInitialScale.z);
            mainThrusterFlame.gameObject.SetActive(flameLength > 0.01f);
        }

        if (thrustAudioSource != null)
        {
            float targetVolume = mainActive || reverseActive ? maxThrustVolume * Mathf.Abs(thrustInput) : 0f;

            if (targetVolume > 0.01f)
            {
                if (!thrustAudioSource.isPlaying)
                    thrustAudioSource.Play();

                thrustAudioSource.volume = Mathf.MoveTowards(thrustAudioSource.volume, targetVolume, Time.deltaTime * 3f);
                thrustAudioSource.pitch = Mathf.Lerp(0.85f, 1.2f, Mathf.Abs(thrustInput));
            }
            else
            {
                thrustAudioSource.volume = Mathf.MoveTowards(thrustAudioSource.volume, 0f, Time.deltaTime * 3f);

                if (thrustAudioSource.volume <= 0.01f && thrustAudioSource.isPlaying)
                    thrustAudioSource.Stop();
            }
        }
    }

    private void StopThrustEffects()
    {
        SetParticleEmission(mainThrusterParticles, false);
        SetParticleEmission(reverseThrusterParticles, false);
        SetParticleEmission(leftStrafeParticles, false);
        SetParticleEmission(rightStrafeParticles, false);

        if (mainThrusterFlame != null)
            mainThrusterFlame.gameObject.SetActive(false);

        if (thrustAudioSource != null && thrustAudioSource.isPlaying)
            thrustAudioSource.Stop();
    }

    private void SetParticleEmission(ParticleSystem particles, bool enabled)
    {
        if (particles == null)
            return;

        ParticleSystem.EmissionModule emission = particles.emission;
        emission.enabled = enabled;

        if (enabled && !particles.isPlaying)
            particles.Play();
        else if (!enabled && particles.isPlaying)
            particles.Stop(false, ParticleSystemStopBehavior.StopEmitting);
    }

    private void OnDrawGizmosSelected()
    {
        if (currentDockingPort == null)
            return;

        Gizmos.color = CanDock ? Color.green : Color.yellow;
        Gizmos.DrawWireSphere(currentDockingPort.position, 0.6f);
        Gizmos.DrawLine(transform.position, currentDockingPort.position);
    }
}
